I’m building a Preact component and I’m unsure whether to use signals or hooks for shared state. Given this code, refactor it to avoid double sources of truth and explain the reasoning:

```tsx
import { signal } from "@preact/signals";

const theme = signal<"light" | "dark">("light");

export function ThemeToggle() {
  const [localTheme, setLocalTheme] = useState(theme.value);

  return (
    <button
      onClick={() => {
        const next = localTheme === "light" ? "dark" : "light";
        setLocalTheme(next);
        theme.value = next;
      }}
    >
      Toggle
    </button>
  );
}
```

